#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAXV 8

static int indegree[MAXV];
static int adj[MAXV][MAXV];
static int done[MAXV];
static int order[MAXV];

static void invalid_input(void) {
    puts("INVALID_INPUT");
    exit(1);
}

static void cycle(void) {
    puts("CYCLE");
    exit(1);
}

int main(int argc, char **argv) {
    if (argc < 3) invalid_input();
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n <= 0 || n > MAXV) invalid_input();
    long m = strtol(argv[2], &endptr, 10);
    if (*endptr != '\0' || m < 0) invalid_input();
    if (argc != 3 + 2 * m) invalid_input();
    memset(indegree, 0, sizeof(indegree));
    memset(adj, 0, sizeof(adj));
    memset(done, 0, sizeof(done));
    for (long i = 0; i < m; ++i) {
        long u = strtol(argv[3 + 2 * i], &endptr, 10);
        if (*endptr != '\0' || u < 0 || u >= n) invalid_input();
        long v = strtol(argv[3 + 2 * i + 1], &endptr, 10);
        if (*endptr != '\0' || v < 0 || v >= n) invalid_input();
        if (!adj[u][v]) {
            adj[u][v] = 1;
            indegree[v]++;
        }
    }
    int out_cnt = 0;
    while (out_cnt < n) {
        int v = -1;
        for (int i = 0; i < n; ++i) {
            if (!done[i] && indegree[i] == 0) { v = i; break; }
        }
        if (v == -1) cycle();
        if (out_cnt > 0) putchar(' ');
        printf("%d", v);
        order[out_cnt++] = v;
        done[v] = 1;
        for (int w = 0; w < n; ++w) {
            if (adj[v][w]) {
                adj[v][w] = 0;
                indegree[w]--;
            }
        }
    }
    putchar('\n');
    return 0;
}
